def smallest_string_after_swaps(s, pairs):
    n = len(s)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    for i, j in pairs:
        union(i, j)

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)

    res = list(s)
    for idxs in groups.values():
        chars = sorted(res[i] for i in idxs)
        for pos, ch in zip(sorted(idxs), chars):
            res[pos] = ch
    return "".join(res)
